import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, relative, resolve } from 'node:path';
import { parseArgs } from 'node:util';
import { fileURLToPath } from 'node:url';

// The gate ships as one file so a plugin hook, an npm bin and a checkout all run the same bytes and
// the reference fingerprint of the gate itself is one hash. The bundler stays deliberately dumb:
// it concatenates the module graph and refuses a name defined twice, rather than renaming behind
// the author's back. `--check` rebuilds and compares, which is what proves the committed bundle.
const ROOT = fileURLToPath(new URL('../', import.meta.url));
const ENTRY = 'packages/ai-engineering-gate/src/main.mjs';
const OUTPUT = 'packages/ai-engineering-gate/dist/ai-engineering-gate.mjs';

const LOCAL_IMPORT = /^import\s[\s\S]*?from\s+'(\.[^']+)';$/gm;
const IMPORT_STATEMENT = /^import\s[\s\S]*?from\s+'[^']+';$/gm;
const BUILTIN_IMPORT = /^import\s+\{([\s\S]*?)\}\s+from\s+'(node:[^']+)';$/gm;
const DECLARATION = /^export\s+(?:default\s+)?(?:async\s+)?(const|let|var|function|class)\s+([A-Za-z0-9_$]+)/gm;
const TOP_LEVEL = /^(?:export\s+)?(?:async\s+)?(?:const|let|var|function|class)\s+([A-Za-z0-9_$]+)/gm;

async function graph(entry) {
  const order = [];
  const seen = new Set();
  const visit = async path => {
    if (seen.has(path)) return;
    seen.add(path);
    const source = await readFile(resolve(ROOT, path), 'utf8');
    for (const [, specifier] of source.matchAll(LOCAL_IMPORT)) {
      await visit(relative(ROOT, resolve(ROOT, dirname(path), specifier)));
    }
    order.push([path, source]);
  };
  await visit(entry);
  return order;
}

// Imports here span several lines, so both the graph walk and the strip work on the whole text with a
// non-greedy match up to the terminating quote, never line by line.
function moduleBody(source) {
  return source.replace(IMPORT_STATEMENT, '').replace(/^export\s+(?=(?:async\s+)?(?:const|let|var|function|class)\s)/gm, '').trim();
}

// Node builtins survive the bundle, merged into one import per module: repeating a named import in a
// single scope is a duplicate binding, so the union is taken rather than the statements kept.
function builtinImports(modules) {
  const named = new Map();
  for (const [path, source] of modules) {
    for (const [statement, clause, specifier] of source.matchAll(BUILTIN_IMPORT)) {
      if (statement.includes(' as ')) {
        throw new Error(`${path} renames a builtin import, which the bundler does not merge: ${statement}`);
      }
      const names = named.get(specifier) ?? new Set();
      for (const name of clause.split(',').map(one => one.trim()).filter(Boolean)) names.add(name);
      named.set(specifier, names);
    }
  }
  return [...named]
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([specifier, names]) => `import { ${[...names].sort().join(', ')} } from '${specifier}';`);
}

function collisions(bodies) {
  const owners = new Map();
  const duplicates = [];
  for (const [path, body] of bodies) {
    for (const [, name] of body.matchAll(TOP_LEVEL)) {
      const owner = owners.get(name);
      if (owner && owner !== path) duplicates.push(`${name}: ${owner} and ${path}`);
      owners.set(name, path);
    }
  }
  return duplicates;
}

async function build() {
  const source = await readFile(resolve(ROOT, ENTRY), 'utf8');
  const exported = [...source.matchAll(DECLARATION)].map(match => match[2]);
  const modules = await graph(ENTRY);
  const bodies = modules.map(([path, text]) => [path, moduleBody(text)]);
  const duplicates = collisions(bodies);
  if (duplicates.length > 0) {
    throw new Error(`the same name is declared in two modules, rename one:\n- ${duplicates.join('\n- ')}`);
  }
  const parts = bodies.map(([path, body]) => `// ${path}\n${body}`);
  return [
    '// Generated by scripts/build-gate-bundle.mjs from packages/ai-engineering-gate/src. Do not edit.',
    builtinImports(modules).join('\n'),
    ...parts,
    `export { ${exported.join(', ')} };`,
    '',
  ].join('\n\n');
}

async function main() {
  const { values } = parseArgs({ options: {
    check: { type: 'boolean', default: false },
    help: { type: 'boolean', default: false },
  } });
  if (values.help) {
    console.log(`usage: node scripts/build-gate-bundle.mjs [--check]\ncheck: report a stale bundle without writing\noutput: ${OUTPUT}`);
    return;
  }
  const bundle = await build();
  const target = resolve(ROOT, OUTPUT);
  let current = null;
  try {
    current = await readFile(target, 'utf8');
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }
  if (current === bundle) {
    console.log(`bundle: current\nbytes: ${bundle.length}`);
    return;
  }
  if (values.check) {
    console.log(`stale: ${OUTPUT}\nhelp: npm run build:gate`);
    process.exitCode = 1;
    return;
  }
  await mkdir(dirname(target), { recursive: true });
  await writeFile(target, bundle);
  console.log(`bundle: written\nbytes: ${bundle.length}`);
}

main().catch(error => {
  console.log(`error: ${error.message}\nhelp: node scripts/build-gate-bundle.mjs --help`);
  process.exitCode = 1;
});
